package com.agraabhi.oshodiscourses.transcript

import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Discourse id to oshoworld transcript page, for the discourses whose page has real text
 * (iOS `TranscriptCatalog`, generated by `scripts/build-transcript-catalog.py`).
 * The audio `id` drives the API fetch; the page `slug` is the scrape fallback.
 */
class TranscriptCatalog(private val entries: Map<String, Entry>) {
    @Serializable
    data class Entry(
        /** oshoworld audio document id, e.g. "66265929d26d4da463e8850d". */
        val id: String,
        /** Page slug, e.g. "ashtavakra-maha-geeta-01". */
        val slug: String,
        /** Word count measured at crawl time; a rough length hint only. */
        val words: Int = 0,
    )

    // Discourse ids are "<seriesID>-<number>" and the number has no hyphen.
    private val countsBySeries: Map<String, Int> by lazy {
        entries.keys.mapNotNull { id -> id.lastIndexOf('-').takeIf { it >= 0 }?.let { id.substring(0, it) } }
            .groupingBy { it }
            .eachCount()
    }

    val mappedDiscourseCount: Int get() = entries.size

    val mappedSeriesCount: Int get() = countsBySeries.size

    val discourseIDs: Set<String> get() = entries.keys

    fun entry(discourseID: String): Entry? = entries[discourseID]

    fun hasTranscript(discourseID: String): Boolean = discourseID in entries

    fun transcriptCount(seriesID: String): Int = countsBySeries[seriesID] ?: 0

    companion object {
        const val API_BASE: String = "https://oshoworld.com/api/server"
        const val SITE_BASE: String = "https://oshoworld.com"
        const val RESOURCE: String = "/TranscriptCatalog.json"

        private val json = Json { ignoreUnknownKeys = true }

        /** JSON endpoint returning `{"description": "<html>"}` or `{"error": true}`. */
        fun descriptionURL(entry: Entry, apiBase: String = API_BASE): String = "$apiBase/audio/get-description/${entry.id}"

        fun pageURL(entry: Entry, siteBase: String = SITE_BASE): String = "$siteBase/${entry.slug}"

        fun decode(text: String): TranscriptCatalog = TranscriptCatalog(json.decodeFromString<Map<String, Entry>>(text))

        /** The shipped catalog from the classpath; empty (transcripts disabled) if it is missing or corrupt. */
        fun loadShipped(): TranscriptCatalog = runCatching {
            val stream = checkNotNull(TranscriptCatalog::class.java.getResourceAsStream(RESOURCE))
            decode(stream.bufferedReader().use { it.readText() })
        }.getOrElse { TranscriptCatalog(emptyMap()) }
    }
}
